attempts = [
    ("A", "timeout", None, None),
    ("B", "answered", "connected", 404),
    ("C", "answered", "refused", None),
]


def classify(dns, tcp, http):
    if dns == "timeout":
        return "Check DNS evidence"
    if tcp == "refused":
        return "Check TCP port"
    if http == 404:
        return "Check HTTP path"
    return "Review the log"


for name, dns, tcp, http in attempts:
    print(name, classify(dns, tcp, http))
